package io.github.likexiang21.tfcplus.agriculture.common.crop;

import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.event.level.BlockEvent;

import java.util.List;

/**
 * Unified harvest replacement for mature A/TFC/B crop blocks (except the six grain crops,
 * which use the bundle path). The original loot is generated by the block's own loot table and
 * then the B seed/waste rules are enforced, so the B logic controls the result instead of only
 * appending to an untouched vanilla/A/TFC drop.
 */
public final class UnifiedCropHarvestHandler {

    public static void onBlockBreak(BlockEvent.BreakEvent event) {
        if (event.isCanceled() || !(event.getLevel() instanceof ServerLevel level)) {
            return;
        }
        final BlockState state = event.getState();
        final String blockId = BuiltInRegistries.BLOCK.getKey(state.getBlock()).toString();
        if (CropBItemResolver.isGrainBlock(blockId)) {
            return;
        }
        if (CropBItemResolver.seedForCropBlock(blockId) == null) {
            return;
        }
        if ("top".equalsIgnoreCase(propertyText(state, "part"))) {
            return;
        }
        final int[] ageAndMax = ageAndMax(state);
        if (ageAndMax[0] < 0 || ageAndMax[1] < 0 || ageAndMax[0] < ageAndMax[1]) {
            return;
        }

        event.setCanceled(true);
        if (event.getPlayer() != null && event.getPlayer().isCreative()) {
            level.removeBlock(event.getPos(), false);
            if ("bottom".equalsIgnoreCase(propertyText(state, "part"))) {
                final var above = event.getPos().above();
                if (level.getBlockState(above).is(state.getBlock())) {
                    level.removeBlock(above, false);
                }
            }
            return;
        }
        final List<ItemStack> original = Block.getDrops(state, level, event.getPos(),
            level.getBlockEntity(event.getPos()), event.getPlayer(),
            event.getPlayer() == null ? ItemStack.EMPTY : event.getPlayer().getMainHandItem());
        for (final ItemStack stack : original) {
            if (!stack.isEmpty()) {
                Block.popResource(level, event.getPos(), stack.copy());
            }
        }

        final Item seed = CropBItemResolver.seedForCropBlock(blockId);
        final int requestedSeeds = CropBItemResolver.seedCountForCropBlock(blockId);
        final int presentSeeds = seed == null ? 0
            : original.stream().filter(s -> s.is(seed)).mapToInt(ItemStack::getCount).sum();
        final int missingSeeds = seed == null ? 0 : Math.max(0, requestedSeeds - presentSeeds);
        if (missingSeeds > 0) {
            Block.popResource(level, event.getPos(), new ItemStack(seed, missingSeeds));
        }
        final ItemStack waste = CropBItemResolver.wasteForCropBlock(blockId);
        if (!waste.isEmpty()) {
            Block.popResource(level, event.getPos(), waste);
        }
        final ItemStack corm = CropBItemResolver.cormForCropBlock(blockId);
        if (!corm.isEmpty()) {
            Block.popResource(level, event.getPos(), corm);
        }
        final ItemStack root = CropBItemResolver.rootForCropBlock(blockId);
        if (!root.isEmpty()) {
            Block.popResource(level, event.getPos(), root);
        }
        final Item product = CropBItemResolver.productForCropBlock(blockId);
        final int productTarget = CropBItemResolver.productCountForCropBlock(blockId);
        final int productPresent = product == null ? 0
            : original.stream().filter(s -> s.is(product)).mapToInt(ItemStack::getCount).sum();
        final int productMissing = product == null ? 0 : Math.max(0, productTarget - productPresent);
        if (productMissing > 0) {
            Block.popResource(level, event.getPos(), new ItemStack(product, productMissing));
        }

        level.removeBlock(event.getPos(), false);
        // Double crops: removing the bottom must also remove the orphaned top block.
        if ("bottom".equalsIgnoreCase(propertyText(state, "part"))) {
            final var above = event.getPos().above();
            if (level.getBlockState(above).is(state.getBlock())) {
                level.removeBlock(above, false);
            }
        }
    }

    private static int[] ageAndMax(BlockState state) {
        int age = -1;
        int max = -1;
        var ageProperty = state.getProperties().stream()
            .filter(p -> p.getName().equals("age"))
            .findFirst().orElse(null);
        if (ageProperty == null) {
            return new int[]{-1, -1};
        }
        if (state.getValue(ageProperty) instanceof Integer value) {
            age = value;
        }
        for (final BlockState possible : state.getBlock().getStateDefinition().getPossibleStates()) {
            if (possible.getValue(ageProperty) instanceof Integer value) {
                max = Math.max(max, value);
            }
        }
        return new int[]{age, max};
    }

    private static String propertyText(BlockState state, String name) {
        for (final var property : state.getProperties()) {
            if (property.getName().equals(name)) {
                return String.valueOf(state.getValue(property));
            }
        }
        return "";
    }

    private UnifiedCropHarvestHandler() {}
}
